"""Preregistered fixed scripts; these are prompts, never recognized transcripts."""
VERSION='m6-v1.0'
LIMITS={'asr':48,'reasoning':45,'tts':54,'commit_item':1}
SESSIONS={}
normal=[('short','What is two plus two?','four'),('long','I have an early exam tomorrow and several chapters left to study. Give me one practical study tip in a single short sentence.','one coherent practical study tip'),('question','What is the capital of France?','Paris'),('context','Name one famous landmark there.','a Paris landmark'),('numbers','What is twelve plus eight?','twenty')]
for letter in 'ABCD':
    SESSIONS[letter]=[{'id':letter+'00','kind':'warmup','script':['Hello.'],'expected':'greeting'}]+[{'id':letter+str(i).zfill(2),'kind':'normal','case':case,'script':[text],'expected':expected} for i,(case,text,expected) in enumerate(normal,1)]
SESSIONS['E']=[{'id':'E00','kind':'warmup','script':['Hello.'],'expected':'greeting'},
 {'id':'E01','kind':'interrupt','script':['Count slowly from one to ten.','When counting is audible around one or two, speak over it: What is two plus two?'],'expected':'old count stops, four, no resumption'},
 {'id':'E02','kind':'interrupt','script':['Count slowly from one to ten.','When counting is audible, speak over it: What is the capital of France?'],'expected':'old count stops, Paris, no resumption'},
 {'id':'E03','kind':'split_replace','script':['Please tell me','Pause about two seconds, then: Actually, what is five plus five?'],'expected':'two actual segments; ten, obsolete request not resumed'}]
SESSIONS['F']=[{'id':'F00','kind':'warmup','script':['Hello.'],'expected':'greeting'},
 {'id':'F01','kind':'split_complete','script':['What is the capital','Pause about two seconds, then: of France?'],'expected':'two actual segments; coherent Paris answer; retain failure if context lost'},
 {'id':'F02','kind':'task','script':['Add five pencils to my shopping list.','Listen to the exact proposal before saying Confirm.','After verified save, say Read my shopping list.'],'expected':'human-correct proposal, direct confirmation, real commit, independent SQL five pencils, spoken list'}]
TRIALS={t['id']:{**t,'session':s} for s,ts in SESSIONS.items() for t in ts}
METHODS={'clock':'time.monotonic_ns; same Pi/boot across main, callback and independent verifier; no cross-host subtraction','user_onset':'first Silero SPEAKING returned to existing processor, .15s start decision; detection proxy, not physical speech onset','speech_end':'Silero QUIET endpoint returned to processor, .7s stop setting; endpoint decision, not last acoustic phoneme','asr_tts':'MCP client request-start to validated result; includes IPC/serialization; not isolated hosted HTTP duration','reasoning':'existing GoogleSpeech.answer entry/return, no retained content','submission':'nonzero PCM output callback return-ready timestamp before wrapper return; software submission proxy, not DAC/acoustic onset','cancellation':'observer immediately before original controller.interrupt; queue clear existing event separately','stop':'first callback-return-ready with epoch>=new epoch, software fence acknowledgment. Drain estimate=last old nonzero submission+reported output latency+callback block duration; not acoustic','physical_audible_onset':'NOT_MEASURED; earphones/no calibrated acoustic capture; human audibility categorical only','physical_speech_onset':'NOT_MEASURED','last_audible_output':'NOT_MEASURED','p95':'nearest rank ceil(.95*n), only n>=20; coarse empirical tail, clustered fixed-script sessions; project reporting rule, not course threshold','trial_policy':'All scheduled, incidental, failed, timed-out, canceled, missing and unstarted retained; no silent reruns.10s minimum between trial cue starts; no response pacing change','strata':'cold greeting TTS, retained first-user warmup, steady normal, interruptions, splits and task separate; restarted-model requests cold, no forced cache flush'}
def get_trial(trial):
    if trial not in TRIALS:raise ValueError('unknown_trial')
    return TRIALS[trial]
